CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(255) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'ROLE_USER', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, type VARCHAR(20) NOT NULL, icon VARCHAR(30) DEFAULT 'tag');
CREATE TABLE IF NOT EXISTS accounts (id BIGINT PRIMARY KEY AUTO_INCREMENT, account_name VARCHAR(255) NOT NULL, account_type VARCHAR(30) NOT NULL, balance DECIMAL(19,2) NOT NULL DEFAULT 0, currency VARCHAR(3) NOT NULL DEFAULT 'INR', user_id BIGINT NOT NULL, CONSTRAINT fk_account_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS budgets (id BIGINT PRIMARY KEY AUTO_INCREMENT, monthly_limit DECIMAL(19,2) NOT NULL, month INT NOT NULL, year INT NOT NULL, user_id BIGINT NOT NULL, category_id BIGINT NOT NULL, CONSTRAINT fk_budget_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_budget_category FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS incomes (id BIGINT PRIMARY KEY AUTO_INCREMENT, amount DECIMAL(19,2) NOT NULL, description VARCHAR(255), date DATE NOT NULL, user_id BIGINT NOT NULL, category_id BIGINT NOT NULL, account_id BIGINT, CONSTRAINT fk_income_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_income_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_income_account FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS expenses (id BIGINT PRIMARY KEY AUTO_INCREMENT, amount DECIMAL(19,2) NOT NULL, description VARCHAR(255), date DATE NOT NULL, user_id BIGINT NOT NULL, category_id BIGINT NOT NULL, account_id BIGINT, payment_method VARCHAR(30) DEFAULT 'CASH', transaction_ref_no VARCHAR(120) UNIQUE, CONSTRAINT fk_expense_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_expense_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_expense_account FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS transaction_splits (id BIGINT PRIMARY KEY AUTO_INCREMENT, expense_id BIGINT NOT NULL, category_id BIGINT NOT NULL, amount DECIMAL(19,2) NOT NULL, note VARCHAR(255), CONSTRAINT fk_split_expense FOREIGN KEY(expense_id) REFERENCES expenses(id), CONSTRAINT fk_split_category FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS savings_goals (id BIGINT PRIMARY KEY AUTO_INCREMENT, goal_name VARCHAR(255) NOT NULL, target_amount DECIMAL(19,2) NOT NULL, current_amount DECIMAL(19,2) NOT NULL DEFAULT 0, deadline DATE, user_id BIGINT NOT NULL, CONSTRAINT fk_goal_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, message VARCHAR(500) NOT NULL, is_read BIT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, user_id BIGINT NOT NULL, CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS upi_integration_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, app_provider VARCHAR(20) NOT NULL, upi_id VARCHAR(255), amount DECIMAL(19,2) NOT NULL, status VARCHAR(20) NOT NULL, raw_payload TEXT, timestamp DATETIME NOT NULL, user_id BIGINT NOT NULL, CONSTRAINT fk_upi_user FOREIGN KEY(user_id) REFERENCES users(id));
